// Presentation content for the v7 design: which photo goes where, the country
// descriptors, the featured projects and the capability and decade panels.
// Facts come from projects.json and company.json; this file only chooses and phrases.
import { projects, projectBySlug, projectUrl, countries, type Project, type Sector } from './data';

/** Photos in public/images/photos (generated by scripts/images.mjs). None shows a specific company project. */
export type PhotoName =
  | 'tower-sky'
  | 'tower-mono'
  | 'desert-lines'
  | 'distribution-pole'
  | 'offshore-platform'
  | 'construction-site'
  | 'engineering-drawings'
  | 'site-engineer'
  | 'industrial-plant'
  | 'substation'
  | 'power-channel'
  | 'pipeline'
  | 'transmission-towers';

export interface CountryMeta {
  region: string;
  descriptor: string;
  photo: PhotoName;
}

export const COUNTRY_META: Record<string, CountryMeta> = {
  pakistan: { region: 'Asia', descriptor: 'Headquarters · Transmission & infrastructure', photo: 'power-channel' },
  libya: { region: 'North Africa', descriptor: 'Transmission & oil-sector power', photo: 'desert-lines' },
  'saudi-arabia': { region: 'Middle East', descriptor: 'Transmission & fibre networks', photo: 'transmission-towers' },
  iraq: { region: 'Middle East', descriptor: 'High-voltage transmission', photo: 'tower-mono' },
  malaysia: { region: 'Asia', descriptor: '500 kV transmission', photo: 'substation' },
  mozambique: { region: 'Africa', descriptor: 'HVDC transmission', photo: 'tower-sky' },
  iran: { region: 'Middle East', descriptor: 'High-voltage transmission', photo: 'distribution-pole' },
};

export function countryMeta(slug: string): CountryMeta {
  const m = COUNTRY_META[slug];
  if (!m) throw new Error(`No country meta for ${slug}`);
  return m;
}

/** Order used on the Home page and Global presence (headquarters first, then by record). */
export const PRESENCE_ORDER = ['pakistan', 'libya', 'saudi-arabia', 'iraq', 'malaysia', 'mozambique', 'iran'].filter((s) =>
  countries.some((c) => c.slug === s),
);

const SECTOR_PHOTOS: Record<Sector, PhotoName[]> = {
  transmission: ['tower-mono', 'desert-lines', 'tower-sky', 'transmission-towers'],
  substation: ['substation'],
  distribution: ['distribution-pole'],
  industrial: ['industrial-plant'],
  'oil-and-gas-electrical': ['offshore-platform', 'industrial-plant'],
  civil: ['construction-site', 'power-channel', 'engineering-drawings'],
  other: ['pipeline', 'site-engineer'],
};

/** A generic photo for a project, chosen by sector (stable per project). Never a photo of the project itself. */
export function projectPhoto(p: Project): PhotoName {
  const list = SECTOR_PHOTOS[p.sector];
  let h = 0;
  for (const ch of p.slug) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return list[h % list.length]!;
}

export interface Slide {
  tag: string;
  title: string;
  href: string;
  photo: PhotoName;
}

const card = (slug: string, title: string, photo: PhotoName): Slide => {
  const p = projectBySlug(slug);
  return { tag: p.country, title, href: projectUrl(p), photo };
};

