// Anchors match the service sections on /services/
const maxKv = Math.max(...projects.filter((p) => p.sector === 'transmission' && p.voltage_kv !== null && !/HVDC/.test(p.name)).map((p) => p.voltage_kv!));
const minKv = Math.min(...projects.filter((p) => p.sector === 'transmission' && p.voltage_kv !== null).map((p) => p.voltage_kv!));
export const MAX_AC_KV = maxKv;

